import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"宽列 Bigtable","description":"","frontmatter":{"title":"宽列 Bigtable","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wide-column-bigtable.md","filePath":"cs/wide-column-bigtable.md","lastUpdated":1789023840000}'),b={name:"cs/wide-column-bigtable.md"};function h(m,a,_,S,u,B){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="宽列-bigtable" tabindex="-1">宽列 Bigtable <a class="header-anchor" href="#宽列-bigtable" aria-label="Permalink to &quot;宽列 Bigtable&quot;">​</a></h1><div class="epigraph"><p>行键、列族、时间戳三维：稀疏、按行键范围切 tablet。不是 SQL 表，也不是 JSON 树；访问路径是行键设计。</p><footer>—— 据 Chang et al., Bigtable, OSDI 2006；Percolator 课的底盘</footer></div><p><a href="/cs/document-db">上一课</a>是嵌套文档。本课是稀疏宽表：Bigtable 模型。缺口是键设计决定局部性——与分片键课同构，粒度到列族。Percolator 已用此底盘做事务；本课模型本身：单行原子、跨行无（除非上层）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表：行键排序，列族分别存（独立 compaction），单元格可多版本时间戳。读一行一列族顺序 I/O。扫描前缀。缺口是<strong>把查询写成行键</strong>：倒置索引、连接预编码进键，否则全表扫。与关系 schema 相反，这里 schema 主要是族与键约定。</p><p>tablet：行键范围分片，再平衡拆范围。底层 SSTable+memtable，即 LSM。</p><p><span class="marginnote">Chang, Dean, Ghemawat et al. OSDI 2006。HBase、Cassandra 宽列变体（Cassandra 另有分区键/聚簇列）。本课 Bigtable 三维。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计行键避免热点（不要纯时间戳开头）。列族按访问共现分，不要一列一族。GC：按版本数或年龄，水位像 MVCC。与 SQL 层：Spanner 在类似存储上加 SQL，键仍要懂。</p><p>布隆、zone：SST 级已有。R 树不在此模型核心。</p>',10)),(e(),s(c,null,{default:l(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RK%5B%22%E8%A1%8C%E9%94%AE%E6%9C%89%E5%BA%8F%22%5D%20--%3E%20TAB%5B%22tablet%20%E8%8C%83%E5%9B%B4%22%5D%0A%20%20CF%5B%22%E5%88%97%E6%97%8F%22%5D%20--%3E%20SST%5B%22%E7%8B%AC%E7%AB%8B%20LSM%22%5D%0A%20%20TS%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E7%89%88%E6%9C%AC%22%5D%20--%3E%20GC%5B%22%E7%89%88%E6%9C%AC%20GC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>局部性：相邻行键一起扫。连接：应用层或预连接进同一行。shuffle 发生在上层 MR/Spark。事务：行内原子；Percolator 跨行。</p><p>与文档：宽列扁平稀疏，路径用列名限定符，不是任意 JSON 深度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲属性图。也不把宽列当 Parquet。时序库常用宽列或倒排时间，后课专门压缩。</p><p>后课默认：宽列靠行键局部性；跨行事务要上层。图数据库：点边一等，多跳遍历是第一查询。</p><p>tablet 拆分就是范围分片，令牌环是另一放置。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bigtable：有序行键、列族、版本；LSM tablet。</li><li>查询能力几乎等于键设计。</li><li>图数据库下一课。</li><li>出处：Chang et al., OSDI 2006；Percolator 对照。</li></ul>',9))])}const E=o(b,[["render",h]]);export{g as __pageData,E as default};
